function automailRefJson(nodeName) {
  try {
    const it = $(nodeName).first();
    return it && it.json && typeof it.json === 'object' ? it.json : null;
  } catch (e) {
    return null;
  }
}
/** Metadane maila: zwykle z Dedup; fallback gdy testujesz pojedynczy node / brak referencji. */
const email =
  automailRefJson('Code_DedupAndTerminGuard') ||
  automailRefJson('Filter_WP_Formularz') ||
  automailRefJson('PrzykladMaila1') ||
  {};
const item = $input.first().json;
const root = item.body && typeof item.body === 'object' ? item.body : item;
const raw = root.choices?.[0]?.message?.content ?? '{}';
let text = typeof raw === 'string' ? raw.trim() : JSON.stringify(raw);
text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/,'').trim();
let data;
try { data = JSON.parse(text); } catch (e) {
  data = {
    parse_error: true,
    is_event_inquiry: false,
    needs_human_review: true,
    event_inquiry_confidence: 'low',
    date_confidence: 'low',
    location_confidence: 'low',
    event_date_start: null,
    event_date_end: null,
    venue_or_city: null,
    client_name: null,
    event_kind: 'other',
    date_inquiry_type: 'none',
    event_kind_clear: false,
    location_clear: false,
    raw_quote: text.slice(0, 200)
  };
}

const bodyLogic = String(email.emailBodyForAi || email.emailBody || '');
const subjChk = String(email.emailSubject || '');
const fullBlob = (subjChk + ' ' + bodyLogic).replace(/\s+/g, ' ').trim();
const isReplyClar = /doprecyzowanie/i.test(subjChk);

function extractFromAddr(ef) {
  const s = String(ef || '');
  const m = s.match(/<([^>\s]+@[^>\s]+)>/);
  if (m) return m[1].trim().toLowerCase();
  if (s.includes('@')) return s.trim().toLowerCase();
  return '';
}
const fromAddrLower = extractFromAddr(email.emailFrom);
const systemAutomatedFrom = !fromAddrLower || /^(wordpress@|formularz@|noreply@|no-?reply@|mailer-daemon@|bounce)/i.test(fromAddrLower) || fromAddrLower === 'biuro@imprezja.pl';
const bodyTrim = bodyLogic.replace(/\s+/g, ' ').trim();
const client_short_followup = !systemAutomatedFrom && bodyTrim.length >= 1 && bodyTrim.length <= 280 && (isReplyClar || /^re\s*:/i.test(subjChk.trim()));

function pad2(n) { return String(n).padStart(2, '0'); }
function lastDay(y, month1to12) {
  return new Date(Date.UTC(y, month1to12, 0)).getUTCDate();
}

/** Rok dla bloku miesięcy gdy klient nie podał roku (np. „czerwiec”, „lipiec i sierpień”). */
function defaultYearForMonths(monthNums, refD) {
  if (!monthNums.length) return null;
  const y = refD.getUTCFullYear();
  const cm = refD.getUTCMonth() + 1;
  const first = monthNums[0];
  if (first >= cm) return y;
  return y + 1;
}

/** Formy miesięcy — dopasowanie bez JS \\b (nie działa z ą/ć/ę/ł/ń/ó/ś/ź/ż). */
const MONTH_FORMS_BY_M = [
  [],
  ['stycznia', 'styczniu', 'styczeń'],
  ['lutego', 'lutym', 'luty'],
  ['marca', 'marcu', 'marzec'],
  ['kwietnia', 'kwietniu', 'kwiecień'],
  ['maja', 'maju', 'maj'],
  ['czerwca', 'czerwcu', 'czerwiec'],
  ['lipca', 'lipcu', 'lipiec'],
  ['sierpnia', 'sierpniu', 'sierpień'],
  ['września', 'wrześniu', 'wrzesień'],
  ['października', 'październiku', 'październik'],
  ['listopada', 'listopadzie', 'listopad'],
  ['grudnia', 'grudniu', 'grudzień'],
];

function textMentionsWord(tl, word) {
  const w = word.toLowerCase();
  let from = 0;
  while (from <= tl.length) {
    const i = tl.indexOf(w, from);
    if (i < 0) return false;
    const prev = i > 0 ? tl[i - 1] : ' ';
    const next = i + w.length < tl.length ? tl[i + w.length] : ' ';
    const prevOk = !/[\p{L}\p{M}]/u.test(prev);
    const nextOk = !/[\p{L}\p{M}]/u.test(next);
    if (prevOk && nextOk) return true;
    from = i + 1;
  }
  return false;
}

function distinctMonthsInText(tl) {
  const low = tl.toLowerCase();
  const out = [];
  for (let mi = 1; mi <= 12; mi++) {
    const forms = MONTH_FORMS_BY_M[mi];
    for (let fi = 0; fi < forms.length; fi++) {
      if (textMentionsWord(low, forms[fi])) {
        out.push(mi);
        break;
      }
    }
  }
  return [...new Set(out)].sort(function (a, b) { return a - b; });
}

const CITIES_PL = (
  'Kalisz Konin Ostrów Wielkopolski Poznań Warszawa Kraków Wrocław Łódź Gdańsk Szczecin Lublin Bydgoszcz ' +
  'Białystok Rzeszów Radom Toruń Kielce Gliwice Zabrze Olsztyn Bielsko-Biała Ruda Śląska Rybnik Tychy ' +
  'Opole Gorzów Elbląg Płock Wałbrzych Włocławek Tarnów Chorzów Koszalin Legnica Grudziądz Słupsk Jaworzno ' +
  'Jastrzębie Nowy Sącz Jelenia Góra Konstancin Leszno Inowrocław Piotrków Sieradz Kutno Września Śrem Kościan'
).split(/\s+/).filter(Boolean);

/** Heurystyki PL dla każdego maila: miesiące (1 lub wiele), miasto, region, wesele. */
function applyInboundPolishHeuristics() {
  if (!fullBlob) return;
  const tl = fullBlob.toLowerCase();
  const t = fullBlob;
  const refD = email.mailDate ? new Date(email.mailDate) : new Date();

  const dmY = t.match(/\b(\d{1,2})[\.\/-](\d{1,2})[\.\/-](20\d{2})\b/);
  if (dmY && !data.event_date_start) {
    const dd = parseInt(dmY[1], 10);
    const mm = parseInt(dmY[2], 10);
    const yy = parseInt(dmY[3], 10);
    if (mm >= 1 && mm <= 12 && dd >= 1 && dd <= 31) {
      data.event_date_start = yy + '-' + pad2(mm) + '-' + pad2(dd);
      data.event_date_end = null;
      data.date_inquiry_type = 'single_day';
      data.date_confidence = 'medium';
    }
  }

  const yMatch = t.match(/\b(20[2-3]\d)\b/);
  const yExp = yMatch ? parseInt(yMatch[1], 10) : null;
  const monthNums = distinctMonthsInText(tl);

  const looksLikeOrdinalWeekday = /\b(pierwsz\w*|drug\w*|trzeci\w*|czwart\w*|ostatn\w*|1\\.\s*|2\\.\s*|3\\.\s*|4\\.\s*)\s+(sobot|niedziel|poniedzia|wtork|środ|czwart|piątek|piątk)/i.test(tl);

  if (monthNums.length && !data.event_date_start && !looksLikeOrdinalWeekday) {
    const y = yExp != null ? yExp : defaultYearForMonths(monthNums, refD);
    if (y != null) {
      const minM = monthNums[0];
      const maxM = monthNums[monthNums.length - 1];
      const ld = lastDay(y, maxM);
      data.event_date_start = y + '-' + pad2(minM) + '-01';
      data.event_date_end = y + '-' + pad2(maxM) + '-' + pad2(ld);
      data.date_inquiry_type = 'month_or_season';
      data.date_confidence = 'medium';
    }
  }

  if (!data.event_date_start && yExp) {
    if (/\blato\b/.test(tl)) {
      data.event_date_start = yExp + '-06-01';
      data.event_date_end = yExp + '-08-31';
      data.date_inquiry_type = 'month_or_season';
      data.date_confidence = 'medium';
    } else if (/\bwakacj/.test(tl)) {
      data.event_date_start = yExp + '-07-01';
      data.event_date_end = yExp + '-08-31';
      data.date_inquiry_type = 'month_or_season';
      data.date_confidence = 'medium';
    }
  }

  const restM = t.match(/restauracja\s+([A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż0-9][\w\-]*(?:\s+[A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż0-9][\w\-]*){0,4})/i);
  if (restM && (!data.venue_or_city || data.location_confidence === 'low')) {
    let restName = restM[1].trim().replace(/\s+(wesele|wesl\w*|ślub|slub|urodzin|imprez|firm\w*|latem|wakacj)\b.*$/i, '').trim();
    data.venue_or_city = ('restauracja ' + restName).slice(0, 120);
    data.location_confidence = 'medium';
    data.location_clear = true;
  }

  for (let ci = 0; ci < CITIES_PL.length; ci++) {
    const city = CITIES_PL[ci];
    const re = new RegExp('\\b' + city.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+') + '\\b', 'i');
    if (re.test(t) && (!data.venue_or_city || data.location_confidence === 'low')) {
      data.venue_or_city = data.venue_or_city || city;
      data.location_confidence = 'medium';
      data.location_clear = true;
      break;
    }
  }

  const regionRe = /\b(wielkopolsk\w*|małopolsk\w*|mazowieck\w*|dolnośląsk\w*|śląsk\w*|łódzk\w*|podkarpack\w*|lubusk\w*|zachodniopomorsk\w*|kujawsko[- ]pomorsk\w*|warmińsko[- ]mazursk\w*|opolsk\w*|podlask\w*|lubelsk\w*|pomorsk\w*)\b/i;
  const rm = t.match(regionRe);
  if (rm && (!data.venue_or_city || data.location_confidence === 'low')) {
    data.venue_or_city = data.venue_or_city || ('region: ' + rm[0]).slice(0, 120);
    data.location_confidence = 'medium';
    data.location_clear = true;
  }

  const okol = t.match(/\bokolic\w*\s+([A-ZĄĆĘŁŃÓŚŹŻ][a-ząćęłńóśźż]{2,28})\b/);
  if (okol && (!data.venue_or_city || data.location_confidence === 'low')) {
    data.venue_or_city = data.venue_or_city || ('okolice ' + okol[1]).slice(0, 120);
    data.location_confidence = 'medium';
    data.location_clear = true;
  }

  if (/\bwesele\b|\bwesl\w*\b|ślub|slub/i.test(tl)) {
    data.event_kind = 'wedding';
    data.event_kind_clear = true;
  }

  if (client_short_followup && !data.venue_or_city && bodyTrim.length <= 200) {
    data.venue_or_city = bodyTrim.slice(0, 160);
    data.location_confidence = 'medium';
    data.location_clear = true;
  }

  data.is_event_inquiry = true;
}

applyInboundPolishHeuristics();

/** Brak daty po AI/heurystykach — tylko krótka odpowiedź w wątku: domyślny 2-miesięczny zakres. */
function applyDefaultRangeAfterClientSupplement() {
  if (!(isReplyClar || client_short_followup)) return;
  if (data.event_date_start) return;
  const md = email.mailDate ? new Date(email.mailDate) : new Date();
  if (Number.isNaN(md.getTime())) return;
  let y = md.getUTCFullYear();
  let m = md.getUTCMonth() + 1;
  let startM = m + 1;
  let startY = y;
  if (startM > 12) { startM = 1; startY += 1; }
  let endM = startM + 1;
  let endY = startY;
  if (endM > 12) { endM = 1; endY += 1; }
  const lastD = lastDay(endY, endM);
  data.event_date_start = startY + '-' + pad2(startM) + '-01';
  data.event_date_end = endY + '-' + pad2(endM) + '-' + pad2(lastD);
  data.date_inquiry_type = 'month_or_season';
  data.date_confidence = 'medium';
  data._inferred_range_short_client_reply = true;
}

applyDefaultRangeAfterClientSupplement();

const dc = String(data.date_confidence || 'low').toLowerCase();
let lc = String(data.location_confidence || 'low').toLowerCase();
const ditRaw = String(data.date_inquiry_type || 'unknown').toLowerCase().replace(/-/g, '_');
let dit = ditRaw;
if (dit !== 'single_day' && dit !== 'month_or_season' && dit !== 'none') dit = 'unknown';

/** Miasto / region z heurystyki lub niepuste venue → wystarczy do jazdy dalej (nie wymagaj high z AI). */
const venueStr = data.venue_or_city ? String(data.venue_or_city).trim() : '';
if (venueStr.length >= 2 && (lc === 'low' || lc === '')) {
  lc = 'medium';
}

function ymd(s) {
  if (!s || typeof s !== 'string') return '';
  const m = s.match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : '';
}
function daySpan(a, b) {
  if (!a || !b) return 0;
  const d1 = new Date(a + 'T12:00:00.000Z');
  const d2 = new Date(b + 'T12:00:00.000Z');
  if (Number.isNaN(d1.getTime()) || Number.isNaN(d2.getTime())) return 9999;
  return Math.abs((d2 - d1) / 86400000);
}

const startY = ymd(data.event_date_start);
const endY = ymd(data.event_date_end || data.event_date_start);
let isRange = dit === 'month_or_season';
const blobAll = String((email.emailSubject || '') + ' ' + bodyLogic + ' ' + (data.raw_quote || ''));
const blobLow = blobAll.toLowerCase();
if (!isRange && startY && endY && startY !== endY && daySpan(startY, endY) >= 7) {
  if (/wolne|termin|sobot|sierp|lipc|czerw|wrze|paźdz|pazdz|listop|grud|stycz|luty|marz|kwiet|maj|wakac|sezon|latem|zimą|zima|jesien|wiosn|które dni|jakie dni|kiedy masz|masz coś wolnego|wesele|ślub|slub/i.test(blobLow)) {
    isRange = true;
  }
}

const MAX_AUTO_RANGE_DAYS = 92;
const spanDays = startY && endY ? daySpan(startY, endY) : 0;
const overbroadAi = data.client_asks_overbroad_availability === true;
const unreasonableAi = data.client_wants_unreasonable_scope === true;
const heuristicYearWide = /\b(cały|cal(y|ego))\s+(20\d{2})\b|\b(20\d{2})\s+rok(u|iem)?\b|\brok\s+(20\d{2})\b|wszystkie\s+sobot(y|ę|e)?\s+(w\s*)?(20\d{2}|roku)/i.test(blobAll);
const greedyHuman = /\bwszystkie\s+wolne\s+terminy\b|\bkażd(ą|a)\s+(sobot|weekend)/i.test(blobAll) || /\b(5|pięć|10|dziesięć)\s+lat\b/i.test(blobAll);

const date_ok = !isRange && (dc === 'high' || dc === 'medium') && !!startY;
const rangeDcOk = dc === 'high' || dc === 'medium';
let date_range_ok = isRange && !!startY && !!endY && rangeDcOk && spanDays <= MAX_AUTO_RANGE_DAYS && !overbroadAi;
if (heuristicYearWide) date_range_ok = false;

const narrow_range_request = isRange && !!startY && !!endY && !date_range_ok && (spanDays > MAX_AUTO_RANGE_DAYS || overbroadAi || heuristicYearWide);

let event_kind_clear = data.event_kind_clear === true;
if (data.event_kind_clear !== true && data.event_kind_clear !== false) {
  event_kind_clear = /\b(wesele|wesl\w*|ślub|slub|osiemnast|urodzin|imienin|studni\w*|firmow\w*|korporac|poprawin|chrzcin|komuni|wigili\w*|sylwest|andrzejki|wieczór panieński|wieczor panienski|styp\w*|jubileusz)\b/i.test(blobAll);
}

let location_clear = data.location_clear === true;
if (data.location_clear !== true && data.location_clear !== false) {
  location_clear = lc === 'high' || lc === 'medium';
}
const location_ok = lc === 'high' || lc === 'medium';

if (client_short_followup) {
  data.needs_human_review = false;
  data.parse_error = false;
  data.is_event_inquiry = true;
}

const isEvt = data.is_event_inquiry === true;
let human = data.parse_error === true || data.needs_human_review === true || !isEvt || unreasonableAi || greedyHuman;
if (unreasonableAi) human = true;
/** HITL (Telegram): każde zapytanie o imprezę = zawsze „human” w metadanych — bez uzależnienia od auto-ścieżki kalendarza/oferty do klienta w tym łańcuchu. */
if (isEvt) {
  human = true;
  data.needs_human_review = true;
}

/** Gdy mamy sensowny zakres dat (np. cały miesiąc), ale date_range_ok z AI/heurystyki = false — i tak idziemy w kalendarz (jeden mail: terminy + dopytanie o miejsce), zamiast osobnego doprecyzowania. */
const spanCal = startY && endY ? daySpan(startY, endY) : 0;
const date_range_ok_calendar =
  human !== true &&
  isEvt === true &&
  narrow_range_request !== true &&
  overbroadAi !== true &&
  heuristicYearWide !== true &&
  unreasonableAi !== true &&
  greedyHuman !== true &&
  !!startY && !!endY && startY <= endY &&
  spanCal >= 1 && spanCal <= MAX_AUTO_RANGE_DAYS;

const DJ_NOTIFY_EMAIL = 'nowaczykdamian@gmail.com';
const mailFromNotify = 'Biuro Imprezja <biuro@imprezja.pl>';
const client_to_email = String(email.wp_form_client_email || email.emailReplyTo || email.emailFrom || '').trim();
const ekRaw = String(data.event_kind || '').trim().toLowerCase();
let event_kind_resolved = (ekRaw === 'wedding' || ekRaw === 'other') ? ekRaw : '';
if (!event_kind_resolved) {
  const blob = String((email.emailSubject || '') + ' ' + bodyLogic).toLowerCase();
  const w = blob.includes('wesele') || blob.includes('wesel') || blob.includes('ślub') || blob.includes('slub');
  event_kind_resolved = w ? 'wedding' : 'other';
}
return [{
  json: {
    ...data,
    automail_termin_flood_dj_note: email.automail_termin_flood_dj_note || '',
    automail_force_human_termin_flood: !!email.automail_force_human_termin_flood,
    date_inquiry_type: dit,
    event_kind: event_kind_resolved,
    date_confidence: dc,
    location_confidence: lc,
    date_ok,
    date_range_ok,
    date_range_ok_calendar,
    narrow_range_request,
    location_ok,
    event_kind_clear,
    location_clear,
    human,
    dj_notify_email: DJ_NOTIFY_EMAIL,
    mail_from_notify: mailFromNotify,
    client_to_email,
    wp_form_name: email.wp_form_name,
    wp_form_phone: email.wp_form_phone,
    wp_form_message: email.wp_form_message,
    emailSubject: email.emailSubject,
    emailBody: email.emailBody,
    emailBodyForAi: email.emailBodyForAi,
    short_client_thread_reply: email.short_client_thread_reply === true,
    client_short_followup,
    inferred_range_short_reply: data._inferred_range_short_client_reply === true,
    emailFrom: email.emailFrom,
    mailDate: email.mailDate
  }
}];

/**
 * Oferty — demo_termin_wolny z Google Calendar (node wcześniej) lub true przy pominięciu API.
 * Szablony: wesele (event_kind wedding) vs inna impreza; PDF i treść osobno.
 */
const j = $input.first().json;
const eventKind = String(j.event_kind || 'other').toLowerCase() === 'wedding' ? 'wedding' : 'other';
const cn = j.client_name ? String(j.client_name) : '';
const dateRaw = j.event_date_start ? String(j.event_date_start) : '';
const dateStr = dateRaw.length >= 10 ? dateRaw.slice(0, 10) : dateRaw;
function isoToPl(d) {
  if (!d || d.length < 10) return d || '';
  const p = d.slice(0, 10).split('-');
  if (p.length !== 3) return d;
  return p[2] + '.' + p[1] + '.' + p[0];
}
const datePl = isoToPl(dateStr);
const dateForSubject = datePl || dateStr || '';
const offerPdfWedding = 'https://imprezja.pl/wp-content/uploads/2026/01/Oferta-wesele-Imprezja-2027.pdf';
const offerPdfOther = 'https://imprezja.pl/wp-content/uploads/2026/01/Oferta-impreza-2027-Damian-Nowaczyk.pdf';
const offerPdfUrl = eventKind === 'wedding' ? offerPdfWedding : offerPdfOther;
const mailFrom = 'Biuro Imprezja <biuro@imprezja.pl>';
const replyTo = 'biuro@imprezja.pl';
const demo_termin_wolny = (j.demo_termin_wolny !== undefined && j.demo_termin_wolny !== null) ? !!j.demo_termin_wolny : true;
const locNote = !j.location_ok ? '<p style="margin-top:1em;border-top:1px solid #eee;padding-top:1em;"><strong>Proszę jeszcze</strong> o podanie <strong>miejscowości lub obiektu</strong> imprezy — ułatwi to wycenę dojazdu i logistyki (można dopisać w odpowiedzi na tego maila).</p>' : '';
function escapeHtml(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
const greeting = cn ? 'Cześć ' + escapeHtml(cn) + ',' : 'Cześć,';
const datePhrase = datePl ? escapeHtml(datePl) : '[data imprezy]';
const pdfBlock = '<p>Tu podrzucam link do pełnej oferty z detalami:<br><a href="' + escapeHtml(offerPdfUrl) + '">' + escapeHtml(offerPdfUrl) + '</a></p>\n';
const wrapOpen = '<div style="font-family:Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.5;color:#222;">\n';
const wrapClose = '\n</div>';
let htmlWolny;
if (eventKind === 'wedding') {
  htmlWolny = wrapOpen +
'<p>' + greeting + '</p>\n' +
'<p>Sprawdziłem kalendarz… i mam dobrą wiadomość: w <strong>' + datePhrase + '</strong> jestem wolny i z przyjemnością rozkręcę <strong>Wasze wesele</strong>.</p>\n' +
'<p>Nazywam się Damian Nowaczyk, od ponad 20 lat kręcę imprezy pod marką Imprezja – od wesel, przez osiemnastki i urodziny, po poprawiny i firmówki. Dzięki temu ogarniam gości w każdym wieku: od przedszkolaków po klub seniora, więc każdy znajdzie coś dla siebie na parkiecie.</p>\n' +
'<p><strong>Jak wygląda wesele ze mną?</strong></p>\n' +
'<ul style="margin:0 0 1em 1.2em;padding:0;">\n' +
'<li>dużo dobrej muzyki – od klasyków po świeże radiowe numery, zawsze dopasowane do Was i Waszych gości,</li>\n' +
'<li>angażujące zabawy, animacje, konkursy i quizy – ale bez żenady,</li>\n' +
'<li>fajna, swobodna atmosfera, w której nie ma miejsca na nudę,</li>\n' +
'<li>scenariusz dopasowany do Was, a nie „szablon z internetu”.</li>\n' +
'</ul>\n' +
'<p><strong>Do tego możecie dorzucić kilka „efektów specjalnych”:</strong></p>\n' +
