    /\n.{0,160}napisała:\s*\n/i,
    /\nFrom:\s.+\nSent:\s/i,
    /\n-----Original Message-----/i,
    /\n_{20,}/,
    /\nDnia\s.+\s+napisał/i,
    /\nLe\s.+\s+a écrit\s*:/i,
  ];
  let cut = s.length;
  for (let ri = 0; ri < markers.length; ri++) {
    const match = markers[ri].exec(s);
    if (match && match.index < cut) cut = match.index;
