function parseStackedLabels(body) {
  const out = {
    wp_form_name: null,
    wp_form_email: null,
    wp_form_phone: null,
    wp_form_message: null,
  };
  if (!body || !String(body).trim()) return out;
  const lines = String(body).split(/\r?\n/).map((l) => l.trim());
  for (let i = 0; i < lines.length; i++) {
    const L = lines[i];
    if (!L) continue;
    let key = null;
    if (/^imię$|^imie$|^name$/i.test(L)) key = 'wp_form_name';
    else if (/^e-?mail$|^email$/i.test(L)) key = 'wp_form_email';
    else if (/^telefon$/i.test(L)) key = 'wp_form_phone';
    else if (/^treść zapytania$/i.test(L) || /^treść$/i.test(L) || /^tresc zapytania$/i.test(L)) key = 'wp_form_message';
    if (!key || out[key]) continue;
    let j = i + 1;
    while (j < lines.length && lines[j] === '') j++;
    if (j >= lines.length) continue;
    const val = lines[j];
    if (!val) continue;
    if (/^(imię|imie|e-?mail|email|telefon|treść|tresc)/i.test(val) && val.length < 40) continue;
