function parseColonLabels(body) {
  const out = {
    wp_form_name: null,
    wp_form_email: null,
    wp_form_phone: null,
    wp_form_message: null,
  };
  let labeledLines = 0;
  const lines = body.split(/\r?\n/);
  let current = null;
  const buf = [];

  const flush = () => {
    if (!current) return;
    const v = buf.join('\n').trim();
    buf.length = 0;
    if (!v) { current = null; return; }
    out[current] = v;
    labeledLines += 1;
    current = null;
  };

  const start = (key, rest) => {
    flush();
    current = key;
    if (rest) buf.push(rest);
  };

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) {
      if (current) buf.push('');
      continue;
    }
    const m = line.match(/^([^:：]{1,48})[:：]\s*(.*)$/);
    if (m) {
      const label = m[1].trim();
      const rest = m[2];
      const L = norm(label);
      if (/imię|^imie$|^name$|twoje imi/i.test(L)) { start('wp_form_name', rest); continue; }
      if (/e\s*mail|^email$|adres e/i.test(L)) { start('wp_form_email', rest); continue; }
